/// Returns the lowest index `i` with `arr[i] == x`, or `-1` when `x` does
/// not occur in `arr`.
///
/// `arr` is sorted in non-decreasing order; `x` is any `i64`.
pub fn first_in_sorted(arr: &[i64], x: i64) -> i64 {
    // Binary search for the first position with arr[pos] >= x.
    let mut lo = 0usize;
    let mut hi = arr.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < arr.len() && arr[lo] == x {
        lo as i64
    } else {
        -1
    }
}

#[cfg(test)]
mod tests {
    use super::first_in_sorted;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(first_in_sorted(&[3, 4, 5, 5, 5, 5, 6], 5), 2);
        assert_eq!(first_in_sorted(&[1, 2], 7), -1);
    }

    #[test]
    fn empty_and_single() {
        assert_eq!(first_in_sorted(&[], 1), -1);
        assert_eq!(first_in_sorted(&[], -5), -1);
        assert_eq!(first_in_sorted(&[42], 42), 0);
        assert_eq!(first_in_sorted(&[42], 41), -1);
        assert_eq!(first_in_sorted(&[42], 43), -1);
    }

    #[test]
    fn edge_values() {
        assert_eq!(first_in_sorted(&[i64::MIN], i64::MIN), 0);
        assert_eq!(first_in_sorted(&[i64::MIN, i64::MIN], i64::MIN), 0);
        assert_eq!(first_in_sorted(&[i64::MIN, i64::MAX], i64::MAX), 1);
        assert_eq!(first_in_sorted(&[i64::MIN, i64::MAX], 0), -1);
        assert_eq!(
            first_in_sorted(&[i64::MAX, i64::MAX, i64::MAX], i64::MAX),
            0
        );
        assert_eq!(first_in_sorted(&[i64::MIN], i64::MAX), -1);
    }

    #[test]
    fn duplicates_at_ends() {
        assert_eq!(first_in_sorted(&[1, 1, 1, 2, 3, 3, 3], 1), 0);
        assert_eq!(first_in_sorted(&[1, 1, 1, 2, 3, 3, 3], 3), 4);
        assert_eq!(first_in_sorted(&[-2, -2, -1, 0, 0, 0, 0], -2), 0);
        assert_eq!(first_in_sorted(&[-2, -2, -1, 0, 0, 0, 0], 0), 3);
    }

    #[test]
    fn large_array() {
        // 1,000,002 ascending values with extra copies of 500_000.
        let mut arr: Vec<i64> = (0..1_000_000i64).collect();
        let start = 500_000usize;
        arr.insert(start + 1, 500_000);
        arr.insert(start + 2, 500_000);
        assert_eq!(first_in_sorted(&arr, 500_000), start as i64);
        assert_eq!(first_in_sorted(&arr, 499_999), start as i64 - 1);
        assert_eq!(first_in_sorted(&arr, 500_001), start as i64 + 3);
        assert_eq!(first_in_sorted(&arr, 2_500_000), -1);
        assert_eq!(first_in_sorted(&arr, -1), -1);
    }

    proptest! {
        #[test]
        fn matches_linear_search(values in prop::collection::vec(any::<i64>(), 0..300),
                                 x in any::<i64>()) {
            let mut arr: Vec<i64> = values;
            arr.sort_unstable(); // guarantees non-decreasing order
            let expected = arr
                .iter()
                .position(|&v| v == x)
                .map(|i| i as i64)
                .unwrap_or(-1);
            let got = first_in_sorted(&arr, x);
            prop_assert_eq!(got, expected);
            // If found, it must be the *lowest* index and arr[got] == x.
            if got >= 0 {
                prop_assert_eq!(arr[got as usize], x);
                prop_assert!(arr[..got as usize].iter().all(|&v| v < x));
            }
        }

        #[test]
        fn matches_linear_search_with_runs(values in prop::collection::vec(any::<i64>(), 1..40)) {
            // Build a sorted array with long duplicate runs.
            let mut arr: Vec<i64> = Vec::new();
            for &v in &values {
                let reps = 1 + (v.wrapping_abs() as usize) % 9;
                for _ in 0..reps {
                    arr.push(v);
                }
            }
            arr.sort_unstable();
            // Pick x from first / last / middle so it always occurs.
            let x = match arr.len() % 3 {
                0 => *arr.first().unwrap(),
                1 => *arr.last().unwrap(),
                _ => arr[arr.len() / 2],
            };
            let expected = arr.iter().position(|&v| v == x).unwrap() as i64;
            let got = first_in_sorted(&arr, x);
            prop_assert_eq!(got, expected);
            prop_assert!(arr[..got as usize].iter().all(|&v| v < x));
        }
    }
}

/// Returns the k-th smallest element of `arr` counting from 0,
/// i.e. the element at index `k` of `arr` sorted in non-decreasing order.
///
/// Repeated values are counted as often as they occur.
///
/// # Panics
///
/// Panics if `k >= arr.len()` (out-of-bounds index).
pub fn kth_smallest(arr: &[i64], k: usize) -> i64 {
    let mut sorted = arr.to_vec();
    sorted.sort_unstable();
    sorted[k]
}

#[cfg(test)]
mod tests {
    use super::kth_smallest;
    use proptest::prelude::*;

    #[test]
    fn example_cases() {
        let arr = [7i64, 1, 7, 3];
        assert_eq!(kth_smallest(&arr, 0), 1);
        assert_eq!(kth_smallest(&arr, 1), 3);
        assert_eq!(kth_smallest(&arr, 2), 7);
        assert_eq!(kth_smallest(&arr, 3), 7);
    }

    #[test]
    fn single_element() {
        assert_eq!(kth_smallest(&[42], 0), 42);
    }

    #[test]
    fn all_equal() {
        let arr = [5i64, 5, 5, 5];
        for k in 0..4 {
            assert_eq!(kth_smallest(&arr, k), 5);
        }
    }

    #[test]
    fn already_sorted_and_reverse() {
        let asc = [1i64, 2, 3, 4, 5];
        let desc = [5i64, 4, 3, 2, 1];
        for k in 0..5 {
            assert_eq!(kth_smallest(&asc, k), (k + 1) as i64);
            assert_eq!(kth_smallest(&desc, k), (k + 1) as i64);
        }
    }

    #[test]
    fn negatives_and_extremes() {
        let arr = [i64::MAX, i64::MIN, 0, -1, 1];
        assert_eq!(kth_smallest(&arr, 0), i64::MIN);
        assert_eq!(kth_smallest(&arr, 1), -1);
        assert_eq!(kth_smallest(&arr, 2), 0);
        assert_eq!(kth_smallest(&arr, 3), 1);
        assert_eq!(kth_smallest(&arr, 4), i64::MAX);
    }

    #[test]
    fn does_not_mutate_input() {
        let arr = vec![3i64, 1, 2];
        let original = arr.clone();
        let _ = kth_smallest(&arr, 1);
        assert_eq!(arr, original);
    }

    proptest! {
        #[test]
        fn prop_matches_sorted_reference(
            values in prop::collection::vec(any::<i64>(), 1..=300),
            k in any::<usize>()
        ) {
            let len = values.len();
            let k = k % len;
            let mut expected = values.clone();
            expected.sort_unstable();
            prop_assert_eq!(kth_smallest(&values, k), expected[k]);
        }
    }
}

/// Returns the length of the longest strictly increasing subsequence of `arr`.
///
/// A subsequence keeps elements in their original order (not necessarily
/// adjacent); each element must be strictly greater than the previous one.
///
/// # Examples
/// ```
/// assert_eq!(solution::lis_length(&[4, 1, 5, 3, 7, 6, 2]), 3);
/// assert_eq!(solution::lis_length(&[2, 2, 2]), 1);
/// assert_eq!(solution::lis_length(&[]), 0);
/// ```
pub fn lis_length(arr: &[i64]) -> usize {
    let n = arr.len();
    if n == 0 {
        return 0;
    }

    // best[i] = length of the longest strictly increasing subsequence
    // that ends exactly at index i (and therefore includes arr[i]).
    let mut best = vec![1usize; n];
    let mut answer = 1usize;

    for i in 0..n {
        for j in 0..i {
            if arr[j] < arr[i] {
                best[i] = best[i].max(best[j] + 1);
            }
        }
        answer = answer.max(best[i]);
    }

    answer
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Brute force: try every subset (bitmask), keep selected elements in
    /// original order, check strict increase, track the maximum size.
    fn brute_force(arr: &[i64]) -> usize {
        let n = arr.len();
        let mut best = 0usize;
        for mask in 0..(1usize << n) {
            let mut last: Option<i64> = None;
            let mut len = 0usize;
            for i in 0..n {
                if (mask & (1 << i)) != 0 {
                    match last {
                        None => {
                            len += 1;
                            last = Some(arr[i]);
                        }
                        Some(l) if l < arr[i] => {
                            len += 1;
                            last = Some(arr[i]);
                        }
                        _ => {}
                    }
                }
            }
            best = best.max(len);
        }
        best
    }

    /// Independent reference: patience-sorting (tails) method.
    /// For strictly increasing, replace the first tail >= x, or append.
    fn tails_reference(arr: &[i64]) -> usize {
        let mut tails: Vec<i64> = Vec::new();
        for &x in arr {
            let pos = tails.partition_point(|&t| t < x);
            match pos {
                p if p < tails.len() => tails[p] = x,
                _ => tails.push(x),
            }
        }
        tails.len()
    }

    #[test]
    fn given_examples() {
        assert_eq!(lis_length(&[4, 1, 5, 3, 7, 6, 2]), 3);
        assert_eq!(lis_length(&[2, 2, 2]), 1);
        assert_eq!(lis_length(&[]), 0);
    }

    #[test]
    fn edge_cases() {
        assert_eq!(lis_length(&[1]), 1);
        assert_eq!(lis_length(&[5, 4, 3, 2, 1]), 1);
        assert_eq!(lis_length(&[1, 2, 3, 4, 5]), 5);
        assert_eq!(lis_length(&[1, 1, 1, 1, 1]), 1);
        assert_eq!(lis_length(&[0, -1, 0, -1, 0]), 2); // e.g. -1, 0
        assert_eq!(lis_length(&[10, 9, 2, 5, 3, 7, 101, 18]), 4); // 2,3,7,18
        assert_eq!(lis_length(&[0, 1, 0, 3, 2, 3]), 4); // 0,1,2,3
        assert_eq!(lis_length(&[3, 3, 3, 2, 1]), 1);
        assert_eq!(lis_length(&[-5, -1, -4, 0, -2]), 3); // -5,-1,0 or -5,-4,0
    }

    #[test]
    fn extreme_values() {
        use std::i64::{MAX, MIN};
        assert_eq!(lis_length(&[MIN, MIN, MAX, MAX]), 2);
        assert_eq!(lis_length(&[MIN, 0, MAX]), 3);
        assert_eq!(lis_length(&[MAX, MIN, MAX]), 2);
        assert_eq!(lis_length(&[MIN, MAX]), 2);
    }

    #[test]
    fn max_length_at_domain_bound() {
        // 100 strictly increasing elements -> length 100.
        let arr: Vec<i64> = (0..100i64).collect();
        assert_eq!(lis_length(&arr), 100);
        // 100 strictly decreasing elements -> length 1.
        let arr: Vec<i64> = (0..100i64).rev().collect();
        assert_eq!(lis_length(&arr), 1);
        // 100 duplicates -> length 1.
        let arr: Vec<i64> = vec![7; 100];
        assert_eq!(lis_length(&arr), 1);
    }

    proptest! {
        #[test]
        fn matches_brute_force_small(arr in prop::collection::vec(any::<i64>(), 0..=12)) {
            prop_assert_eq!(lis_length(&arr), brute_force(&arr));
        }

        #[test]
        fn matches_brute_force_small_values(arr in prop::collection::vec(-5..=5i64, 0..=12)) {
            prop_assert_eq!(lis_length(&arr), brute_force(&arr));
        }

        #[test]
        fn matches_tails_reference(arr in prop::collection::vec(any::<i64>(), 0..=100)) {
            prop_assert_eq!(lis_length(&arr), tails_reference(&arr));
        }

        #[test]
        fn bounds_hold(arr in prop::collection::vec(any::<i64>(), 0..=100)) {
            let l = lis_length(&arr);
            if arr.is_empty() {
                prop_assert_eq!(l, 0);
            } else {
                prop_assert!((1..=arr.len()).contains(&l));
            }
        }

        #[test]
        fn strictly_increasing_gives_full_length(len in 0..=100usize, base in -10_000..=10_000i64) {
            let arr: Vec<i64> = (0..len).map(|i| base + i as i64).collect();
            prop_assert_eq!(lis_length(&arr), len);
        }

        #[test]
        fn strictly_decreasing_gives_one(len in 1..=100usize, base in -10_000..=10_000i64) {
            let arr: Vec<i64> = (0..len).map(|i| base - i as i64).collect();
            prop_assert_eq!(lis_length(&arr), 1);
        }
    }
}

/// Rearrange `a` into the next permutation of its elements in lexicographic
/// order and return `true`. When `a` is already the last permutation
/// (non-increasing), rearrange it into the first one (sorted in
/// non-decreasing order) and return `false`.
///
/// Repeated values count once per arrangement (i.e. we consider distinct
/// arrangements of the multiset of values).
pub fn next_permutation(a: &mut [i64]) -> bool {
    if a.len() < 2 {
        // A single element (or nothing) is both the first and the last
        // permutation: nothing to rearrange.
        return false;
    }

    // Step 1: Find the largest index `i` such that a[i] < a[i + 1]
    // (the pivot of the next permutation).
    let mut i = a.len() - 2;
    while i > 0 && a[i] >= a[i + 1] {
        i -= 1;
    }
    if a[i] >= a[i + 1] {
        // No ascent anywhere: `a` is the last permutation.
        // Reset to the first one (non-decreasing order) and report false.
        a.reverse();
        return false;
    }

    // Step 2: Find the largest index `j > i` such that a[j] > a[i].
    // The suffix a[i + 1..] is non-increasing, so scanning from the right
    // finds the rightmost element strictly greater than a[i].
    // Such a `j` is guaranteed to exist: a[i + 1] > a[i].
    let mut j = a.len() - 1;
    while a[j] <= a[i] {
        j -= 1;
    }

    // Step 3: Swap the pivot with that element, then reverse the suffix
    // (it was non-increasing; reversed it is the smallest possible suffix).
    a.swap(i, j);
    a[i + 1..].reverse();

    true
}

#[cfg(test)]
mod tests {
    use super::next_permutation;
    use proptest::prelude::*;

    fn permutations_of(mut a: Vec<i64>) -> Vec<Vec<i64>> {
        let mut result = vec![a.clone()];
        while next_permutation(&mut a) {
            result.push(a.clone());
        }
        result
    }

    #[test]
    fn given_examples() {
        let mut a = vec![3, 2, 4, 1];
        assert!(next_permutation(&mut a));
        assert_eq!(a, vec![3, 4, 1, 2]);

        let mut b = vec![3, 2, 1];
        assert!(!next_permutation(&mut b));
        assert_eq!(b, vec![1, 2, 3]);
    }

    #[test]
    fn empty_and_single() {
        let mut a: Vec<i64> = vec![];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, Vec::<i64>::new());

        let mut b = vec![42];
        assert!(!next_permutation(&mut b));
        assert_eq!(b, vec![42]);
    }

    #[test]
    fn two_elements() {
        let mut a = vec![1, 2];
        assert!(next_permutation(&mut a));
        assert_eq!(a, vec![2, 1]);

        let mut b = vec![2, 1];
        assert!(!next_permutation(&mut b));
        assert_eq!(b, vec![1, 2]);

        // Equal elements: only one distinct permutation.
        let mut c = vec![5, 5];
        assert!(!next_permutation(&mut c));
        assert_eq!(c, vec![5, 5]);
    }

    #[test]
    fn duplicates_112() {
        // The distinct permutations of [1,1,2] are exactly three.
        let perms = permutations_of(vec![1, 1, 2]);
        assert_eq!(perms, vec![vec![1, 1, 2], vec![1, 2, 1], vec![2, 1, 1]]);
    }

    #[test]
    fn matches_bruteforce() {
        // Build the list of distinct permutations (via the function itself,
        // starting from sorted order), then for every arrangement check that
        // the function returns exactly the smallest arrangement strictly
        // greater than it — or wraps to the first arrangement with `false`.
        fn distinct_perms(sorted: &mut Vec<i64>) -> Vec<Vec<i64>> {
            let mut result = vec![sorted.clone()];
            while next_permutation(sorted) {
                result.push(sorted.clone());
            }
            result
        }

        fn brute_next(arr: &[i64], perms: &[Vec<i64>]) -> Option<Vec<i64>> {
            perms.iter().find(|p| p.as_slice() > arr).cloned()
        }

        let cases: Vec<Vec<i64>> = vec![
            vec![1, 1, 1],
            vec![2, 1, 1, 2],
            vec![1, 3, 1, 3, 2],
            vec![5, 5, 5, 5],
            vec![3, 1, 2, 1, 3, 2],
            vec![-2, -2, 1, 0, -1],
            vec![0, 1, 0, -1, 0],
        ];

        for case in cases {
            let mut sorted = case.clone();
            sorted.sort();
            let perms = distinct_perms(&mut sorted);

            // The generated list must be distinct and sorted lexicographically.
            assert!(perms.windows(2).all(|w| w[0] < w[1]));

            for p in &perms {
                let mut cur = p.clone();
                let returned = next_permutation(&mut cur);
                match brute_next(p, &perms) {
                    Some(next) => {
                        assert!(returned, "case {:?} at {:?}: expected true", case, p);
                        assert_eq!(cur, next, "case {:?} at {:?}", case, p);
                    }
                    None => {
                        assert!(!returned, "case {:?} at {:?}: expected false", case, p);
                        assert_eq!(cur, sorted, "case {:?} at {:?}", case, p);
                    }
                }
            }
        }
    }

    #[test]
    fn full_cycle_of_1234() {
        let perms = permutations_of(vec![1, 2, 3, 4]);
        assert_eq!(perms.len(), 24);
        assert!(perms.windows(2).all(|w| w[0] < w[1]));
        assert_eq!(perms.first().unwrap(), &vec![1, 2, 3, 4]);
        assert_eq!(perms.last().unwrap(), &vec![4, 3, 2, 1]);
    }

    #[test]
    fn last_permutation_wraps_to_first() {
        let mut a = vec![4, 3, 2, 1];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, vec![1, 2, 3, 4]);
        // The next permutation of the first one is the second one.
        assert!(next_permutation(&mut a));
        assert_eq!(a, vec![1, 2, 4, 3]);
    }

    #[test]
    fn non_increasing_wraps() {
        let mut a = vec![9, 7, 7, 5, 5, 5, 0];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, vec![0, 5, 5, 5, 7, 7, 9]);
    }

    #[test]
    fn negatives() {
        let mut a = vec![-1, -2, -3];
        assert!(!next_permutation(&mut a));
        assert_eq!(a, vec![-3, -2, -1]);

        let mut b = vec![-3, -1, -2];
        assert!(next_permutation(&mut b));
        assert_eq!(b, vec![-2, -3, -1]);
    }

    #[test]
    fn large_input() {
        // 1000 elements: values 1..=1000 in reverse order must wrap to
        // sorted order and return false.
        let mut a: Vec<i64> = (0..1000).map(|x| 1000 - x).collect();
        assert!(!next_permutation(&mut a));
        let expected: Vec<i64> = (1..=1000).collect();
        assert_eq!(a, expected);

        // The first permutation [1..=1000]: its next permutation only
        // touches the last two elements...
        let mut c: Vec<i64> = (1..=1000).collect();
        assert!(next_permutation(&mut c));
        let mut expected_c: Vec<i64> = (1..=1000).collect();
        expected_c.swap(998, 999); // -> [1..998, 1000, 999]
        assert_eq!(c, expected_c);

        // ...and the one after that touches the last three:
        // [1..996, 998, 1000, 999] -> [1..996, 999, 998, 1000].
        assert!(next_permutation(&mut c));
        let mut expected_c2: Vec<i64> = (1..=996).collect();
        expected_c2.extend_from_slice(&[999, 998, 1000]);
        assert_eq!(c, expected_c2);
    }

    proptest! {
        #[test]
        fn prop_roundtrip_and_bruteforce(
            init in proptest::collection::vec(
                any::<u8>().prop_map(|x| (x % 5) as i64 - 2),
                0..7
            )
        ) {
            // Build the full list of distinct permutations of `init` starting
            // from sorted order, then check every arrangement.
            let mut sorted = init.clone();
            sorted.sort();
            let mut perms: Vec<Vec<i64>> = vec![sorted.clone()];
            while next_permutation(&mut sorted) {
                perms.push(sorted.clone());
            }

            // Distinct and lexicographically increasing.
            assert!(perms.windows(2).all(|w| w[0] < w[1]));

            for p in &perms {
                let mut cur = p.clone();
                let expected = perms.iter().find(|q| q.as_slice() > p.as_slice()).cloned();
                let returned = next_permutation(&mut cur);
                match expected {
                    Some(next) => {
                        assert!(returned, "at {:?}, list {:?}", p, perms);
                        assert_eq!(cur, next, "at {:?}, list {:?}", p, perms);
                    }
                    None => {
                        assert!(!returned, "at {:?}, list {:?}", p, perms);
                        assert_eq!(cur, sorted, "at {:?}, list {:?}", p, perms);
                    }
                }
            }
        }

        #[test]
        fn prop_cycle_length(n in 1usize..6) {
            // With n distinct elements the full cycle has n! steps and ends
            // back at the first permutation.
            let mut a: Vec<i64> = (1..=n as i64).collect();
            let mut count = 0;
            loop {
                count += 1;
                if !next_permutation(&mut a) {
                    break;
                }
            }
            let fact: u64 = (1..=n as u64).product();
            assert_eq!(count as u64, fact, "n = {}", n);
            assert_eq!(a, (1..=n as i64).collect::<Vec<i64>>());
        }
    }
}

/// Counts the number of distinct ways (as coin multisets, order-insensitive)
/// to make exactly `total` using unlimited copies of the given coin values.
///
/// `total == 0` has exactly one way (use no coins).
///
/// Input domain: at most 12 distinct positive coin values, each in `1..=500`,
/// `total` in `0..=500`; the result fits in `u64`.
pub fn count_change(coins: &[i64], total: i64) -> u64 {
    if total < 0 {
        return 0;
    }
    let total = total as usize;
    let mut dp = vec![0u64; total + 1];
    dp[0] = 1;
    for &coin in coins {
        // Spec guarantees coin >= 1; be defensive anyway.
        if coin <= 0 {
            continue;
        }
        let coin = coin as usize;
        if coin > total {
            continue;
        }
        // Processing coin types in a fixed order and scanning amounts upward
        // counts each multiset of coins exactly once.
        for t in coin..=total {
            dp[t] += dp[t - coin];
        }
    }
    dp[total]
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Independent recursive reference: choose how many coins of type `idx`
    /// to use (0..=total/coin), then recurse on the remaining coin types.
    fn brute(coins: &[i64], total: i64, idx: usize) -> u64 {
        if total == 0 {
            return 1;
        }
        if idx == coins.len() {
            return 0;
        }
        let c = coins[idx];
        let mut sum = 0;
        for k in 0..=total / c {
            sum += brute(coins, total - k * c, idx + 1);
        }
        sum
    }

    #[test]
    fn statement_examples() {
        assert_eq!(count_change(&[1, 5, 10, 25], 11), 4);
        assert_eq!(count_change(&[2], 3), 0);
        assert_eq!(count_change(&[], 0), 1);
    }

    #[test]
    fn zero_total_is_always_one_way() {
        assert_eq!(count_change(&[], 0), 1);
        assert_eq!(count_change(&[7], 0), 1);
        assert_eq!(count_change(&[1, 5, 10, 25], 0), 1);
        let big: Vec<i64> = (489..=500).collect();
        assert_eq!(count_change(&big, 0), 1);
    }

    #[test]
    fn coins_larger_than_total_contribute_nothing() {
        assert_eq!(count_change(&[5, 10], 3), 0);
        assert_eq!(count_change(&[500], 499), 0);
        assert_eq!(count_change(&[500], 500), 1);
        assert_eq!(count_change(&[499, 500], 500), 1);
        assert_eq!(count_change(&[250, 500], 500), 2);
    }

    #[test]
    fn single_coin() {
        assert_eq!(count_change(&[3], 9), 1);
        assert_eq!(count_change(&[3], 10), 0);
        assert_eq!(count_change(&[1], 500), 1);
    }

    #[test]
    fn known_small_cases() {
        assert_eq!(count_change(&[1, 2, 5], 5), 4);
        assert_eq!(count_change(&[1, 2, 5], 10), 10);
        assert_eq!(count_change(&[3, 7], 23), 1); // only 7*2 + 3*3
        // Classic US coin change: 242 ways to make a dollar.
        assert_eq!(count_change(&[1, 5, 10, 25], 100), 242);
    }

    #[test]
    fn order_of_coins_does_not_matter() {
        assert_eq!(count_change(&[25, 1, 10, 5], 11), count_change(&[1, 5, 10, 25], 11));
        assert_eq!(count_change(&[25, 10, 5, 1], 100), count_change(&[1, 5, 10, 25], 100));
        let ascending: Vec<i64> = (1..=12).collect();
        let descending: Vec<i64> = (1..=12).rev().collect();
        assert_eq!(count_change(&descending, 500), count_change(&ascending, 500));
    }

    #[test]
    fn large_inputs_finish_and_stay_consistent() {
        // 12 distinct coins, max total: must not panic (no overflow) and the
        // answer must be positive and independent of coin order.
        let coins: Vec<i64> = (1..=12).collect();
        let a = count_change(&coins, 500);
        assert!(a > 0);
        // 12 large coins near the upper bound.
        let coins: Vec<i64> = (489..=500).collect();
        let b = count_change(&coins, 500);
        assert!(b >= 1 && b <= (1u64 << 12)); // at most one coin of each of 12 kinds
        assert_eq!(count_change(&[499, 500], 500), 1);
    }

    proptest! {
        #[test]
        fn matches_brute_force(
            coin_list in proptest::collection::vec(1i64..41, 0..=10),
            total in 0i64..121,
        ) {
            let mut coins: Vec<i64> = coin_list;
            coins.sort();
            coins.dedup();
            prop_assert_eq!(count_change(&coins, total), brute(&coins, total, 0));
        }

        #[test]
        fn matches_brute_force_wide_values(
            coin_list in proptest::collection::vec(1i64..501, 0..=12),
            total in 0i64..121,
        ) {
            let mut coins: Vec<i64> = coin_list;
            coins.sort();
            coins.dedup();
            prop_assert_eq!(count_change(&coins, total), brute(&coins, total, 0));
        }

        #[test]
        fn independent_of_coin_order(
            coin_list in proptest::collection::vec(1i64..501, 0..=12),
            total in 0i64..501,
            seed in any::<u64>(),
        ) {
            let mut coins: Vec<i64> = coin_list;
            coins.sort();
            coins.dedup();
            let base = count_change(&coins, total);
            // Deterministic Fisher-Yates shuffle driven by the seed.
            let mut state = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
            for i in (1..coins.len()).rev() {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                let j = (state >> 32) as usize % (i + 1);
                coins.swap(i, j);
            }
            prop_assert_eq!(count_change(&coins, total), base);
        }

        #[test]
        fn single_coin_characterization(
            c in 1i64..501,
            t in 0i64..501,
        ) {
            let expect = if t % c == 0 { 1 } else { 0 };
            prop_assert_eq!(count_change(&[c], t), expect);
        }

        #[test]
        fn coin_bigger_than_total_is_irrelevant(
            c in 1i64..502,
            coin_list in proptest::collection::vec(1i64..501, 0..=12),
            total in 0i64..501,
        ) {
            if c <= total {
                return Ok(());
            }
            let mut coins: Vec<i64> = coin_list;
            coins.push(c);
            coins.sort();
            coins.dedup();
            let without: Vec<i64> = coins.iter().copied().filter(|&x| x <= total).collect();
            prop_assert_eq!(count_change(&coins, total), count_change(&without, total));
        }
    }
}

/// 0/1 knapsack: item `i` has weight `weights[i]` and value `values[i]`.
/// Each item may be taken at most once. Returns the largest total value of a
/// selection of items whose total weight is at most `capacity` (0 when
/// nothing fits).
///
/// The implementation uses the classic one-dimensional dynamic program
/// `dp[c]` = best value with total weight at most `c`, iterating items one
/// by one and capacities in descending order so each item is used at most
/// once. Total values stay within i64 for the documented input domain
/// (30 items * 1e15 < i64::MAX).
pub fn knapsack(capacity: usize, weights: &[i64], values: &[i64]) -> i64 {
    // dp[c] = best value achievable with total weight at most c.
    let mut dp = vec![0i64; capacity + 1];
    for (w, v) in weights.iter().zip(values.iter()) {
        let w = *w as usize; // safe: weights are in 1..=1000
        if w > capacity {
            continue; // item cannot fit; its transitions would be out of range
        }
        // 0/1: iterate capacities in descending order so each item is used once.
        for c in (w..=capacity).rev() {
            let candidate = dp[c - w] + v;
            if candidate > dp[c] {
                dp[c] = candidate;
            }
        }
    }
    dp[capacity]
}

#[cfg(test)]
mod tests {
    use super::knapsack;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(knapsack(100, &[60, 50, 20, 20, 8, 3], &[10, 8, 4, 4, 3, 2]), 19);
        assert_eq!(knapsack(5, &[5], &[7]), 7);
    }

    #[test]
    fn basics() {
        // Nothing fits.
        assert_eq!(knapsack(0, &[1, 2], &[5, 6]), 0);
        assert_eq!(knapsack(3, &[4, 5], &[100, 100]), 0);
        // Empty item list.
        assert_eq!(knapsack(10, &[], &[]), 0);
        // Take everything.
        assert_eq!(knapsack(10, &[1, 2, 3], &[10, 20, 30]), 60);
        // Zero-value items.
        assert_eq!(knapsack(10, &[1, 2], &[0, 0]), 0);
        // Single item exactly at capacity, max weight/value.
        assert_eq!(knapsack(1000, &[1000], &[1_000_000_000_000_000]), 1_000_000_000_000_000);
        // Big values: totals must fit in i64 (30 * 1e15 < i64::MAX).
        let weights = vec![1000; 30];
        let values = vec![1_000_000_000_000_000; 30];
        assert_eq!(knapsack(1000, &weights, &values), 1_000_000_000_000_000);
        // 0/1 semantics: an item is not reusable.
        assert_eq!(knapsack(10, &[5, 5], &[7, 7]), 14);
        assert_eq!(knapsack(5, &[5, 5], &[7, 7]), 7);
        // Capacity larger than total weight: take all.
        assert_eq!(knapsack(1000, &[3, 4], &[9, 10]), 19);
    }

    fn brute_force(capacity: usize, weights: &[i64], values: &[i64]) -> i64 {
        let n = weights.len();
        let mut best = 0i64;
        for mask in 0..(1u64 << n) {
            let mut w = 0usize;
            let mut v = 0i64;
            for i in 0..n {
                if mask >> i & 1 == 1 {
                    w += weights[i] as usize;
                    v += values[i];
                }
            }
            if w <= capacity && v > best {
                best = v;
            }
        }
        best
    }

    proptest! {
        /// Random instances in (a subset of) the input domain vs. exact
        /// brute force over all 2^n subsets.
        #[test]
        fn matches_bruteforce(
            capacity in 0usize..=1000,
            weights in prop::collection::vec(1i64..=1000, 0usize..=12),
            values in prop::collection::vec(0i64..=1_000_000_000_000_000, 0usize..=12),
        ) {
            let n = weights.len().min(values.len());
            let got = knapsack(capacity, &weights[..n], &values[..n]);
            let want = brute_force(capacity, &weights[..n], &values[..n]);
            prop_assert_eq!(got, want);
        }

        /// Same property with values derived from weights (a different value
        /// distribution than the uniform case above).
        #[test]
        fn matches_bruteforce_derived_values(
            capacity in 0usize..=1000,
            weights in prop::collection::vec(1i64..=1000, 0usize..=12),
        ) {
            let values: Vec<i64> = weights.iter().map(|w| w * 999_999_999_999).collect();
            let got = knapsack(capacity, &weights, &values);
            let want = brute_force(capacity, &weights, &values);
            prop_assert_eq!(got, want);
        }

        /// Monotonicity: more capacity never decreases the optimum.
        #[test]
        fn monotone(
            capacity in 0usize..=1000,
            weights in prop::collection::vec(1i64..=1000, 0usize..=12),
            values in prop::collection::vec(0i64..=1_000_000_000_000_000, 0usize..=12),
        ) {
            let n = weights.len().min(values.len());
            let w = &weights[..n];
            let v = &values[..n];
            let a = knapsack(capacity, w, v);
            let b = knapsack(1000.min(capacity + 1), w, v);
            prop_assert!(a <= b);
        }
    }
}

//! Levenshtein (edit) distance for slices of `i64`.

/// Returns the Levenshtein distance between `a` and `b`: the minimum number
/// of single-element edits (insert, delete, or replace one element) needed
/// to turn `a` into `b`.
pub fn edit_distance(a: &[i64], b: &[i64]) -> usize {
    let n = a.len();
    let m = b.len();
    if n == 0 {
        return m;
    }
    if m == 0 {
        return n;
    }

    // Classic DP with two rolling rows.
    // prev[j] = distance between a[..i] and b[..j] for the previous i.
    let mut prev: Vec<usize> = (0..=m).collect();
    let mut cur: Vec<usize> = vec![0; m + 1];

    for i in 1..=n {
        cur[0] = i;
        for j in 1..=m {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            let insert = prev[j] + 1; // insert b[j-1] into a
            let delete = cur[j - 1] + 1; // delete a[i-1]
            let replace = prev[j - 1] + cost; // replace a[i-1] with b[j-1]
            cur[j] = insert.min(delete).min(replace);
        }
        std::mem::swap(&mut prev, &mut cur);
    }

    prev[m]
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples_from_statement() {
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 3]), 1);
        assert_eq!(edit_distance(&[5, 6], &[7, 8]), 2);
        assert_eq!(edit_distance(&[], &[4, 4]), 2);
        assert_eq!(edit_distance(&[4, 4], &[]), 2);
    }

    #[test]
    fn basics() {
        assert_eq!(edit_distance(&[], &[]), 0);
        assert_eq!(edit_distance(&[1], &[1]), 0);
        assert_eq!(edit_distance(&[1], &[2]), 1);
        assert_eq!(edit_distance(&[1, 2], &[1, 2]), 0);
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 2, 3]), 0);
        // symmetric
        assert_eq!(
            edit_distance(&[1, 2, 3, 4], &[3, 1, 4]),
            edit_distance(&[3, 1, 4], &[1, 2, 3, 4])
        );
        assert_eq!(edit_distance(&[1, 1, 1, 2, 2], &[1, 2, 2, 2, 2]), 2);
        assert_eq!(edit_distance(&[1, 2, 3], &[]), 3);
        assert_eq!(edit_distance(&[], &[1]), 1);
        // one insertion
        assert_eq!(edit_distance(&[1, 3], &[1, 2, 3]), 1);
        // one deletion
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 3]), 1);
        // one replacement
        assert_eq!(edit_distance(&[1, 2, 3], &[1, 9, 3]), 1);
    }

    #[test]
    fn max_lengths() {
        let a: Vec<i64> = (0..64).collect();
        let b: Vec<i64> = (0..64).collect();
        assert_eq!(edit_distance(&a, &b), 0);
        let c: Vec<i64> = (1..=64).collect();
        // shifted version: delete 0, insert 64
        assert_eq!(edit_distance(&a, &c), 2);
        // disjoint values, same length -> 64 replacements
        let d: Vec<i64> = (64..128).collect();
        assert_eq!(edit_distance(&a, &d), 64);
        // a without one element
        let mut e: Vec<i64> = a.clone();
        e.pop();
        assert_eq!(edit_distance(&a, &e), 1);
        // duplicates
        let f: Vec<i64> = vec![7; 64];
        assert_eq!(edit_distance(&f, &f), 0);
        let g: Vec<i64> = vec![7; 63];
        assert_eq!(edit_distance(&f, &g), 1);
        // a with its first element removed
        let h: Vec<i64> = (0..64).skip(1).collect();
        assert_eq!(edit_distance(&a, &h), 1);
        // every other element kept
        let i: Vec<i64> = (0..64).step_by(2).collect();
        assert_eq!(edit_distance(&a, &i), 32);
    }

    // Naive recursive reference implementation for small inputs.
    fn naive(a: &[i64], b: &[i64]) -> usize {
        if a.is_empty() {
            return b.len();
        }
        if b.is_empty() {
            return a.len();
        }
        if a[0] == b[0] {
            return naive(&a[1..], &b[1..]);
        }
        1 + naive(a, &b[1..]) // insert
            .min(naive(&a[1..], b)) // delete
            .min(naive(&a[1..], &b[1..])) // replace
    }

    proptest! {
        #[test]
        fn matches_naive_short(a in prop::collection::vec(any::<i64>(), 0..8usize),
                               b in prop::collection::vec(any::<i64>(), 0..8usize)) {
            prop_assert_eq!(edit_distance(&a, &b), naive(&a, &b));
        }

        #[test]
        fn metric_properties(a in prop::collection::vec(any::<i64>(), 0..64usize),
                             b in prop::collection::vec(any::<i64>(), 0..64usize),
                             c in prop::collection::vec(any::<i64>(), 0..64usize)) {
            let ab = edit_distance(&a, &b);
            let bc = edit_distance(&b, &c);
            let ac = edit_distance(&a, &c);
            // symmetry
            prop_assert_eq!(ab, edit_distance(&b, &a));
            // triangle inequality: d(a,c) <= d(a,b) + d(b,c)
            prop_assert!(ac <= ab + bc);
            // upper bound: at most max(n, m) edits (replace then delete/insert)
            prop_assert!(ab <= a.len().max(b.len()));
            // lower bound: must account for the length difference
            prop_assert!(ab >= a.len().abs_diff(b.len()));
        }

        #[test]
        fn single_edits(a in prop::collection::vec(any::<i64>(), 0..64usize),
                        i in 0..65usize,
                        v in any::<i64>()) {
            // insert one element
            let mut b = a.clone();
            if i <= b.len() {
                b.insert(i, v);
                prop_assert!(edit_distance(&a, &b) <= 1);
            }
            // delete one element
            let mut c = a.clone();
            if i < c.len() {
                c.remove(i);
                prop_assert!(edit_distance(&a, &c) <= 1);
            }
            // replace one element
            let mut d = a.clone();
            if !d.is_empty() {
                let idx = i % d.len();
                d[idx] = v;
                prop_assert!(edit_distance(&a, &d) <= 1);
            }
        }
    }
}

//! Returns the length of the longest run of consecutive elements that occurs
//! in both slices (longest common substring, not subsequence).

/// Computes the length of the longest contiguous sequence of equal elements
/// shared by `a` and `b`.
///
/// This is the classic "longest common substring" dynamic program:
/// `dp[i][j]` is the length of the common run ending at `a[i-1]` / `b[j-1]`.
///
/// # Examples
/// ```
/// assert_eq!(solution::common_substring(&[1, 2, 3, 4], &[9, 2, 3, 9]), 2);
/// assert_eq!(solution::common_substring(&[1, 2], &[3]), 0);
/// ```
pub fn common_substring(a: &[i64], b: &[i64]) -> usize {
    let (n, m) = (a.len(), b.len());
    if n == 0 || m == 0 {
        return 0;
    }

    let mut dp = vec![vec![0usize; m + 1]; n + 1];
    let mut best = 0usize;

    for i in 1..=n {
        for j in 1..=m {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if dp[i][j] > best {
                    best = dp[i][j];
                }
            }
            // else dp[i][j] stays 0
        }
    }

    best
}

#[cfg(test)]
mod tests {
    use super::common_substring;
    use proptest::prelude::*;

    /// Naive triple-loop: tries every length (largest first) and every pair of
    /// start positions. Only practical for small slices.
    fn brute(a: &[i64], b: &[i64]) -> usize {
        let (n, m) = (a.len(), b.len());
        let max_len = n.min(m);
        for len in (1..=max_len).rev() {
            for i in 0..=n - len {
                for j in 0..=m - len {
                    if a[i..i + len] == b[j..j + len] {
                        return len;
                    }
                }
            }
        }
        0
    }

    /// Independent reference: from each start pair (i, j) expand forward while
    /// elements match; take the maximum. O(n*m*k), fast even at size 64.
    fn expand(a: &[i64], b: &[i64]) -> usize {
        let mut best = 0usize;
        for i in 0..a.len() {
            for j in 0..b.len() {
                let mut k = 0;
                while i + k < a.len() && j + k < b.len() && a[i + k] == b[j + k] {
                    k += 1;
                }
                if k > best {
                    best = k;
                }
            }
        }
        best
    }

    #[test]
    fn given_examples() {
        assert_eq!(common_substring(&[1, 2, 3, 4], &[9, 2, 3, 9]), 2);
        assert_eq!(common_substring(&[1, 2], &[3]), 0);
    }

    #[test]
    fn empty_slices() {
        assert_eq!(common_substring(&[], &[]), 0);
        assert_eq!(common_substring(&[1], &[]), 0);
        assert_eq!(common_substring(&[], &[1, 1, 1]), 0);
    }

