        assert_eq!(common_substring(&[1, 2, 3, 4], &[1, 2, 3]), 3);
        assert_eq!(common_substring(&[4, 3, 2, 1], &[2, 1]), 2); // runs are not reversed
        assert_eq!(common_substring(&[1, 2, 1, 2], &[2, 1, 2]), 3);
