        assert_eq!(common_substring(&a, &b), 63);
        let c: Vec<i64> = vec![-7; 64];
        assert_eq!(common_substring(&a, &c), 0);
    }

    proptest! {
        #[test]
        fn prop_matches_naive_small_alphabet(
            a in prop::collection::vec((0..6i64).prop_map(Into::into), 0..=16),
            b in prop::collection::vec((0..6i64).prop_map(Into::into), 0..=16),
