            prop_assert_eq!(common_substring(&a, &b), expand(&a, &b));
        }

        #[test]
        fn prop_matches_expand_full_domain(
            a in prop::collection::vec(any::<i64>(), 0..=64),
            b in prop::collection::vec(any::<i64>(), 0..=64),
        ) {
            // Full input domain size; expand() is O(n*m*k) so it stays fast.
            prop_assert_eq!(common_substring(&a, &b), expand(&a, &b));
        }

        #[test]
        fn prop_matches_expand_arbitrary_values(
            a in prop::collection::vec(any::<i64>(), 0..=24),
            b in prop::collection::vec(any::<i64>(), 0..=24),
        ) {
            prop_assert_eq!(common_substring(&a, &b), expand(&a, &b));
            prop_assert_eq!(common_substring(&a, &b), brute(&a, &b));
        }

        #[test]
        fn prop_bounds(
            a in prop::collection::vec(any::<i64>(), 0..=64),
            b in prop::collection::vec(any::<i64>(), 0..=64),
        ) {
            let ans = common_substring(&a, &b);
            prop_assert!(ans <= a.len().min(b.len()));
            // If one slice is exactly a substring of the other, answer is its length.
            if b.len() <= a.len() {
                let found = (0..=a.len() - b.len()).any(|i| a[i..i + b.len()] == b[..]);
                if found {
                    prop_assert_eq!(ans, b.len());
                }
            }
        }
    }
