/// Return the number of primes p with p <= n.
///
/// Implemented with the Sieve of Eratosthenes. Works for any `n`;
/// the stated input domain is `n <= 20000`.
pub fn count_primes(n: u64) -> u64 {
    if n < 2 {
        return 0;
    }

    let limit = (n as usize).min(usize::MAX);
    // is_prime[i] == true means i has not yet been sieved out (i.e. still prime).
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    let mut i = 2usize;
    while i * i <= limit {
        if is_prime[i] {
            let mut j = i * i;
            while j <= limit {
                is_prime[j] = false;
                j += i;
            }
        }
        i += 1;
    }

    let count = is_prime.iter().filter(|&&p| p).count();
    count as u64
}

#[cfg(test)]
mod tests {
    use super::count_primes;
    use proptest::prelude::*;

    /// Independent trial-division reference for small n.
    fn is_prime_ref(x: u64) -> bool {
        if x < 2 {
            return false;
        }
        let mut d = 2u64;
        while d * d <= x {
            if x % d == 0 {
                return false;
            }
            d += 1;
        }
        true
    }

    fn count_primes_ref(n: u64) -> u64 {
        (2..=n).filter(|&x| is_prime_ref(x)).count() as u64
    }

    #[test]
    fn small_values() {
        assert_eq!(count_primes(0), 0);
        assert_eq!(count_primes(1), 0);
        assert_eq!(count_primes(2), 1);
        assert_eq!(count_primes(3), 2);
        assert_eq!(count_primes(4), 2);
        assert_eq!(count_primes(5), 3);
        assert_eq!(count_primes(10), 4);
        assert_eq!(count_primes(11), 5);
        assert_eq!(count_primes(20), 8);
    }

    #[test]
    fn known_prime_counts() {
        // pi(100) = 25, pi(1000) = 168, pi(10000) = 1229, pi(20000) = 2262
        assert_eq!(count_primes(100), 25);
        assert_eq!(count_primes(1000), 168);
        assert_eq!(count_primes(10000), 1229);
        assert_eq!(count_primes(20000), 2262);
    }

    proptest! {
        #[test]
        fn matches_trial_division(n in 0u64..=20000) {
            prop_assert_eq!(count_primes(n), count_primes_ref(n));
        }

        #[test]
        fn monotone_non_decreasing(a in 0u64..=20000, b in 0u64..=20000) {
            let lo = a.min(b);
            let hi = a.max(b);
            prop_assert!(count_primes(lo) <= count_primes(hi));
        }
    }
}

//! In-place counting sort for slices whose elements lie in `0..k`.

/// Sorts `a` in non-decreasing order in place using counting sort.
///
/// # Preconditions
/// - `k` is in `1..=64`
/// - every element of `a` is in `0..k`
///
/// All elements (duplicates included) are kept.
pub fn counting_sort(a: &mut [i64], k: i64) {
    // k is in 1..=64 by the input domain.
    let k = k as usize;
    let mut counts = vec![0i64; k];
    for &x in a.iter() {
        counts[x as usize] += 1;
    }
    let mut pos = 0usize;
    for (value, &count) in counts.iter().enumerate() {
        for _ in 0..count {
            a[pos] = value as i64;
            pos += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::counting_sort;
    use proptest::prelude::*;

    #[test]
    fn example_from_statement() {
        let mut a = vec![3, 0, 3, 1];
        counting_sort(&mut a, 5);
        assert_eq!(a, vec![0, 1, 3, 3]);
    }

    #[test]
    fn empty_slice() {
        let mut a: Vec<i64> = Vec::new();
        counting_sort(&mut a, 1);
        assert!(a.is_empty());
    }

    #[test]
    fn single_element() {
        let mut a = vec![0];
        counting_sort(&mut a, 1);
        assert_eq!(a, vec![0]);

        let mut a = vec![63];
        counting_sort(&mut a, 64);
        assert_eq!(a, vec![63]);
    }

    #[test]
    fn already_sorted() {
        let mut a = vec![0, 0, 1, 2, 2, 2, 4];
        counting_sort(&mut a, 5);
        assert_eq!(a, vec![0, 0, 1, 2, 2, 2, 4]);
    }

    #[test]
    fn reverse_sorted() {
        let mut a = vec![4, 3, 2, 1, 0];
        counting_sort(&mut a, 5);
        assert_eq!(a, vec![0, 1, 2, 3, 4]);
    }

    #[test]
    fn all_duplicates() {
        let mut a = vec![2, 2, 2, 2, 2];
        counting_sort(&mut a, 64);
        assert_eq!(a, vec![2, 2, 2, 2, 2]);
    }

    #[test]
    fn k_minus_one_max_value() {
        let mut a = vec![63, 0, 63, 0, 63];
        counting_sort(&mut a, 64);
        assert_eq!(a, vec![0, 0, 63, 63, 63]);
    }

    proptest! {
        // k_raw is in 1..=64 and a's values are in 0..64; raising k to
        // max+1 when needed keeps every element in 0..k while staying
        // inside the allowed k range.
        #[test]
        fn matches_std_sort(k_raw in 1i64..=64, mut a in prop::collection::vec(0i64..64, 0..1000)) {
            let k = k_raw.max(a.iter().max().copied().unwrap_or(0) + 1);
            let mut expected = a.clone();
            expected.sort();
            counting_sort(&mut a, k);
            prop_assert_eq!(a, expected);
        }

        #[test]
        fn preserves_multiset(k_raw in 1i64..=64, mut a in prop::collection::vec(0i64..64, 0..1000)) {
            let k = k_raw.max(a.iter().max().copied().unwrap_or(0) + 1);
            let mut expected_counts = [0i64; 64];
            for &x in a.iter() {
                expected_counts[x as usize] += 1;
            }
            let len = a.len();
            counting_sort(&mut a, k);
            // Length unchanged, result non-decreasing, same multiset.
            prop_assert_eq!(a.len(), len);
            prop_assert!(a.windows(2).all(|w| w[0] <= w[1]));
            let mut actual_counts = [0i64; 64];
            for &x in a.iter() {
                prop_assert!((0..k).contains(&x));
                actual_counts[x as usize] += 1;
            }
            prop_assert_eq!(actual_counts, expected_counts);
        }
    }
}

/// Returns `true` when the sequence of parentheses is properly nested.
///
/// Each element is `1` for an opening parenthesis and `-1` for a closing one.
/// The sequence is balanced iff the running count of open parentheses never
/// drops below zero and ends at exactly zero.
pub fn balanced(p: &[i64]) -> bool {
    let mut depth: i64 = 0;
    for &x in p {
        match x {
            1 => depth += 1,
            -1 => depth -= 1,
            _ => return false, // outside the stated input domain; be defensive
        }
        if depth < 0 {
            return false;
        }
    }
    depth == 0
}

#[cfg(test)]
mod tests {
    use super::balanced;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert!(balanced(&[1, 1, -1, -1]));
        assert!(!balanced(&[-1, 1]));
        assert!(!balanced(&[1]));
        assert!(balanced(&[]));
    }

    #[test]
    fn more_cases() {
        assert!(balanced(&[1, -1]));
        assert!(balanced(&[1, 1, 1, -1, -1, -1]));
        assert!(balanced(&[1, 1, -1, 1, -1, -1]));
        assert!(!balanced(&[1, -1, 1, -1, 1]));
        assert!(!balanced(&[-1]));
        assert!(!balanced(&[1, 1, -1]));
        assert!(!balanced(&[1, 1, -1, -1, -1, 1]));
        assert!(!balanced(&[-1, -1]));
        // Long balanced sequence (max size 1000).
        let long: Vec<i64> = std::iter::repeat(1).take(500)
            .chain(std::iter::repeat(-1).take(500))
            .collect();
        assert!(balanced(&long));
    }

    /// Brute-force reference: count open parentheses explicitly.
    fn reference(p: &[i64]) -> bool {
        let mut open: usize = 0;
        for &x in p {
            match x {
                1 => open += 1,
                -1 => {
                    if open == 0 {
                        return false;
                    }
                    open -= 1;
                }
                _ => return false,
            }
        }
        open == 0
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(500))]
        #[test]
        fn prop_matches_reference(
            p in prop::collection::vec(prop_oneof![Just(1i64), Just(-1i64)], 0..=1000)
        ) {
            prop_assert_eq!(balanced(&p), reference(&p));
        }

        #[test]
        fn prop_mirrored_sequence(p in prop::collection::vec(prop_oneof![Just(1i64), Just(-1i64)], 0..=100)) {
            // Reversing and negating preserves balance:
            // mirror of [1,-1, 1,1,-1,-1] is [-1,-1,-1,1, 1,-1].
            let mirror: Vec<i64> = p.iter().rev().map(|&x| -x).collect();
            prop_assert_eq!(balanced(&p), balanced(&mirror));
        }

        #[test]
        fn prop_prefix_never_negative_implies_consistency(p in prop::collection::vec(prop_oneof![Just(1i64), Just(-1i64)], 0..=200)) {
            // If the running sum never goes negative and ends at 0, must be balanced.
            let mut sum = 0i64;
            let mut ok = true;
            for &x in &p {
                sum += x;
                if sum < 0 { ok = false; break; }
            }
            if ok && sum == 0 {
                prop_assert!(balanced(&p));
            }
        }
    }
}

/// Returns the binomial coefficient C(n, k), the number of ways to choose
/// k items out of n (entry k of row n of Pascal's triangle).
///
/// Returns 0 when `k > n`.
///
/// # Notes
/// - Uses the symmetry C(n, k) == C(n, n - k) to loop at most n/2 times.
/// - Uses the multiplicative formula
///   `C(n, k) = prod_{i=1..=k} (n - i + 1) / i`, which is exact at every
///   step because `C(n, i-1) * (n - i + 1) == C(n, i) * i`.
/// - For n <= 67 the final result is at most C(67, 33) and fits in u64;
///   the intermediate products fit in u128, so no overflow can occur.
pub fn binomial(n: u64, k: u64) -> u64 {
    if k > n {
        return 0;
    }
    // C(n, k) == C(n, n - k); use the smaller of the two to do less work.
    let k = k.min(n - k);

    let mut res: u128 = 1;
    let mut i: u64 = 1;
    while i <= k {
        // Exact division: res == C(n, i-1), so res * (n - i + 1) == C(n, i) * i.
        res = (res * (n - i + 1) as u128) / i as u128;
        i += 1;
    }
    res as u64
}

#[cfg(test)]
mod tests {
    use super::binomial;
    use proptest::prelude::*;

    /// Reference implementation: Pascal's triangle computed in u128
    /// (no overflow possible for n <= 67).
    fn ref_binomial(n: u64, k: u64) -> u128 {
        if k > n {
            return 0;
        }
        let k = k.min(n - k);
        let mut row = vec![1u128; (k + 1) as usize];
        for r in 1..=n {
            let upper = r.min(k);
            for c in (1..=upper).rev() {
                row[c as usize] += row[(c - 1) as usize];
            }
        }
        row[k as usize]
    }

    #[test]
    fn examples() {
        assert_eq!(binomial(5, 2), 10);
        assert_eq!(binomial(4, 0), 1);
        assert_eq!(binomial(3, 4), 0);
    }

    #[test]
    fn boundary_values() {
        assert_eq!(binomial(0, 0), 1);
        assert_eq!(binomial(0, 1), 0);
        assert_eq!(binomial(1, 0), 1);
        assert_eq!(binomial(1, 1), 1);
        assert_eq!(binomial(1, 2), 0);
        // k == u64::MAX must not panic and returns 0.
        assert_eq!(binomial(67, u64::MAX), 0);
        // n == k.
        assert_eq!(binomial(67, 67), 1);
    }

    #[test]
    fn max_value() {
        // C(67, 33) = C(67, 34) is the largest coefficient for n <= 67.
        assert_eq!(binomial(67, 33), 14_226_520_737_620_288_370);
        assert_eq!(binomial(67, 34), 14_226_520_737_620_288_370);
        assert!(14_226_520_737_620_288_370u64 <= u64::MAX);
    }

    proptest! {
        #[test]
        fn matches_pascal(n in 0u64..=67, k in any::<u64>()) {
            let expected = if k > n { 0u128 } else { ref_binomial(n, k) };
            assert_eq!(binomial(n, k) as u128, expected);
        }

        #[test]
        fn symmetry(n in 0u64..=67, k in 0u64..=67) {
            prop_assume!(k <= n);
            assert_eq!(binomial(n, k), binomial(n, n - k));
        }

        #[test]
        fn pascals_identity(n in 0u64..=66, k in 0u64..=66) {
            // C(n, k) + C(n, k+1) = C(n+1, k+1); the sum equals C(n+1, k+1)
            // <= C(67, 33) which fits in u64, so no overflow in debug builds.
            assert_eq!(
                binomial(n, k) + binomial(n, k + 1),
                binomial(n + 1, k + 1)
            );
        }
    }
}
